// Web-sized versions of the files in originals/, generated by `npm run images`.
// Pass the original's path, e.g. thumb('/images/Hilary.jpg').
const sized = (size: string) => (src: string) =>
  src.replace('/images/', `/images/${size}/`).replace(/\.\w+$/, '.webp');

export const thumb = sized('thumb'); // grid cards and other small placements
export const full = sized('full'); // heroes and lightbox slides
